#!/usr/bin/env python3
"""Offline failure fixtures for the actual shared-contract shell entry points.

Fake buf/protoc executables exercise export/staging/commit failure boundaries.
The separate shared-grpc-api-contracts CI job checks real generated bytes with
the pinned generators and upstream schema. These fixtures do not emulate protobuf.
"""

import hashlib
import os
from pathlib import Path
import shutil
import subprocess
import tempfile
import unittest

ROOT = Path(__file__).resolve().parents[2]
CONTRACTS = ROOT / "Proto/shared-grpc-api-contracts.sh"


class SharedContractsTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.bin = self.root / "bin"
        self.bin.mkdir()
        self.env = dict(os.environ, PATH=f"{self.bin}{os.pathsep}{os.environ['PATH']}",
                        GIT_CONFIG_GLOBAL=os.devnull, GIT_CONFIG_NOSYSTEM="1",
                        TMPDIR=str(self.root))

    def executable(self, name, text):
        path = self.bin / name
        path.write_text(text)
        path.chmod(0o755)

    def shell(self, script, *args, **env):
        return subprocess.run(["bash", "-euo", "pipefail", "-c", script, "fixture", *map(str, args)],
                              env=dict(self.env, **env), text=True, capture_output=True, timeout=20)

    def git(self, repository, *args):
        return subprocess.check_output(["git", "-C", str(repository), *args], env=self.env, text=True).strip()

    def test_authoritative_policy_accepts_ancestor_and_refuses_off_master_pin(self):
        repository = self.root / "policy-repo"
        subprocess.run(["git", "init", "-q", "-b", "master", str(repository)], env=self.env, check=True)
        self.git(repository, "config", "user.name", "Fixture")
        self.git(repository, "config", "user.email", "fixture@example.invalid")
        self.git(repository, "commit", "--allow-empty", "-qm", "base")
        ancestor = self.git(repository, "rev-parse", "HEAD")
        self.git(repository, "switch", "-qc", "untrusted")
        self.git(repository, "commit", "--allow-empty", "-qm", "not on master")
        off_master = self.git(repository, "rev-parse", "HEAD")
        self.git(repository, "switch", "-q", "master")
        self.git(repository, "commit", "--allow-empty", "-qm", "current policy")
        policy = self.root / "check-pin.sh"
        policy.write_text('#!/bin/bash\nset -euo pipefail\ngit -C "$POLICY_REPO" merge-base --is-ancestor "$1" master\n')
        self.executable("curl", '''#!/bin/bash
set -euo pipefail
[[ "$*" == *"https://raw.githubusercontent.com/wendylabsinc/service-protos/master/tools/check-pin.sh"* ]] || exit 99
[[ "${FAIL_FETCH:-0}" != 1 ]] || exit 22
while [ "$1" != --output ]; do shift; done
cp "$POLICY_SCRIPT" "$2"
''')
        script = 'source "$1"; SHARED_GRPC_API_CONTRACTS_REF="$2"; check_shared_grpc_api_contracts_ancestry'
        for pin, expected in ((ancestor, 0), (off_master, 1)):
            with self.subTest(pin=pin):
                result = self.shell(script, CONTRACTS, pin, POLICY_REPO=str(repository), POLICY_SCRIPT=str(policy))
                self.assertEqual(result.returncode, expected, result.stderr)
        result = self.shell(script, CONTRACTS, ancestor, POLICY_REPO=str(repository), POLICY_SCRIPT=str(policy), FAIL_FETCH="1")
        self.assertEqual(result.returncode, 22, result.stderr)

    def test_catalogue_aliases_and_exceptions(self):
        self.executable("buf", '#!/bin/sh\nexit "${BUF_STATUS:-0}"\n')
        for local_path, exception, success in (
            (None, "", True),
            ("apps.proto", "", False),
            ("cloud/apps.proto", "", False),
            ("wendylite/v1/sensorlink.proto", "", False),
            ("wendy/lite/sensorlink.proto", "", False),
            ("service/nested.proto", "", False),
            ("cloud/apps.proto", "cloud/apps.proto", True),
            ("apps.proto", "cloud/apps.proto", False),
            ("cloud/apps.proto", "cloud/*.proto", False),
            ("cloud/apps.proto", "../apps.proto", False),
            ("cloud/apps.proto", "missing.proto", False),
        ):
            with self.subTest(local=local_path, exception=exception), tempfile.TemporaryDirectory(dir=self.root) as directory:
                proto, catalogue = Path(directory) / "local", Path(directory) / "catalogue"
                proto.mkdir(); catalogue.mkdir()
                for name in ("apps.proto", "wendylite/v1/sensorlink.proto", "service/nested.proto", "retained.proto"):
                    path = catalogue / name
                    path.parent.mkdir(parents=True, exist_ok=True)
                    path.write_text('syntax = "proto3";\n')
                (proto / "retained.proto").write_text("retained local schema\n")
                if local_path:
                    path = proto / local_path
                    path.parent.mkdir(parents=True, exist_ok=True)
                    path.write_text("stale local schema\n")
                result = self.shell('source "$1"; SHARED_GRPC_API_CONTRACTS_LOCAL_EXCEPTIONS=(retained.proto); '
                                    'if [ -n "$4" ]; then SHARED_GRPC_API_CONTRACTS_LOCAL_EXCEPTIONS+=("$4"); fi; '
                                    'check_shared_grpc_api_contracts_sources "$2" "$3"', CONTRACTS, proto, catalogue, exception)
                self.assertEqual(result.returncode == 0, success, result.stderr)
                if success:
                    failed_parser = self.shell('source "$1"; SHARED_GRPC_API_CONTRACTS_LOCAL_EXCEPTIONS=(); '
                                               'check_shared_grpc_api_contracts_sources "$2" "$3"',
                                               CONTRACTS, proto, catalogue, BUF_STATUS="27")
                    self.assertEqual(failed_parser.returncode, 27)

    def test_missing_catalogue_and_duplicate_or_symlink_exceptions_fail(self):
        self.executable("buf", '#!/bin/sh\nexit 0\n')
        proto, catalogue = self.root / "local", self.root / "catalogue"
        proto.mkdir(); catalogue.mkdir()
        script = 'source "$1"; SHARED_GRPC_API_CONTRACTS_LOCAL_EXCEPTIONS=(); check_shared_grpc_api_contracts_sources "$2" "$3"'
        for directory in (catalogue, self.root / "absent"):
            self.assertNotEqual(self.shell(script, CONTRACTS, proto, directory).returncode, 0)
        (catalogue / "apps.proto").write_text("schema")
        (proto / "apps.proto").write_text("local")
        duplicate = 'source "$1"; SHARED_GRPC_API_CONTRACTS_LOCAL_EXCEPTIONS=(apps.proto apps.proto); check_shared_grpc_api_contracts_sources "$2" "$3"'
        self.assertNotEqual(self.shell(duplicate, CONTRACTS, proto, catalogue).returncode, 0)
        (proto / "apps.proto").unlink()
        (proto / "apps.proto").symlink_to(catalogue / "apps.proto")
        symlink = 'source "$1"; SHARED_GRPC_API_CONTRACTS_LOCAL_EXCEPTIONS=(apps.proto); check_shared_grpc_api_contracts_sources "$2" "$3"'
        self.assertNotEqual(self.shell(symlink, CONTRACTS, proto, catalogue).returncode, 0)

    def test_generation_failures_and_check_mode_preserve_committed_output(self):
        workspace = self.root / "workspace"
        (workspace / "go/scripts").mkdir(parents=True)
        (workspace / "Proto").mkdir()
        shutil.copy2(ROOT / "go/scripts/generate-proto.sh", workspace / "go/scripts")
        (workspace / "Proto/shared-grpc-api-contracts.sh").write_text(
            CONTRACTS.read_text() + '\nSHARED_GRPC_API_CONTRACTS_LOCAL_EXCEPTIONS=(retained.proto)\n')
        (workspace / "Proto/retained.proto").write_text("retained local schema\n")
        self.executable("go", '#!/bin/sh\n[ "$*" = "env GOPATH" ] || exit 99\nprintf "%s\\n" "$TMPDIR"\n')
        self.executable("buf", '''#!/usr/bin/env python3
import os, pathlib, sys
args = sys.argv[1:]
if args == ['--version']: print('1.75.0'); sys.exit(0)
if args[0] == 'build': sys.exit(0)
assert args[0] == 'export', args
if os.environ.get('FAULT') == 'export': sys.exit(23)
out = pathlib.Path(args[args.index('--output') + 1]); out.mkdir(parents=True)
paths = [args[i+1] for i, arg in enumerate(args) if arg == '--path'] or ['apps.proto', 'retained.proto']
if os.environ.get('FAULT') == 'missing-selected' and '--path' in args: paths = paths[1:]
for name in paths:
    path = out / name; path.parent.mkdir(parents=True, exist_ok=True); path.write_text('schema')
''')
        self.executable("protoc", '''#!/usr/bin/env python3
import os, pathlib, sys
args = sys.argv[1:]
if args == ['--version']:
    print('libprotoc ' + ('99.0' if os.environ.get('FAULT') == 'version' else '34.0')); sys.exit(0)
if os.environ.get('FAULT') == 'compile' and any('agent/services/v2/' in arg for arg in args): sys.exit(24)
out = pathlib.Path(next(a.split('=', 1)[1] for a in args if a.startswith('--go_out=')))
if any(a.endswith('recording.proto') for a in args): out = out / 'proto/gen/recordingpb'
out.mkdir(parents=True, exist_ok=True)
(out / 'fixture.pb.go').write_text('changed' if os.environ.get('FAULT') == 'drift' else 'generated')
''')
        self.executable("protoc-gen-go", '#!/bin/sh\necho "protoc-gen-go v1.36.11"\n')
        self.executable("protoc-gen-go-grpc", '#!/bin/sh\necho "protoc-gen-go-grpc 1.6.2"\n')
        committed = workspace / "go/proto/gen"
        committed.mkdir(parents=True)
        (committed / "sentinel.pb.go").write_text("previous code\n")
        def snapshot():
            return {str(p.relative_to(committed)): hashlib.sha256(p.read_bytes()).hexdigest()
                    for p in committed.rglob('*') if p.is_file()}
        script = workspace / "go/scripts/generate-proto.sh"
        before = snapshot()
        for fault in ("version", "export", "missing-selected", "compile"):
            for mode in ("", "--check-shared-grpc-api-contracts", "--shared-grpc-api-contracts-only"):
                with self.subTest(fault=fault, mode=mode):
                    result = self.shell('bash "$1" ${2:+"$2"}', script, mode, FAULT=fault,
                                        WENDY_PROTO_SKIP_VERSION_CHECK="0")
                    self.assertNotEqual(result.returncode, 0, result.stdout)
                    self.assertEqual(snapshot(), before, result.stderr)
        generated = self.shell('bash "$1"', script, WENDY_PROTO_SKIP_VERSION_CHECK="0")
        self.assertEqual(generated.returncode, 0, generated.stderr)
        self.assertNotEqual(snapshot(), before)
        before = snapshot()
        check = self.shell('bash "$1" --check-shared-grpc-api-contracts', script, WENDY_PROTO_SKIP_VERSION_CHECK="0")
        self.assertEqual(check.returncode, 0, check.stderr)
        drift = self.shell('bash "$1" --check-shared-grpc-api-contracts', script, FAULT="drift", WENDY_PROTO_SKIP_VERSION_CHECK="0")
        self.assertNotEqual(drift.returncode, 0)
        self.assertEqual(snapshot(), before)


if __name__ == "__main__":
    unittest.main()
